// This file is generated by AI.

// 通用确认框: 一次性的"要不要做这件事"请求。
//
// 与 `unsaved.ts` 同一套路 —— 请求方把动作存成模块级单例, 打开 store 里的开关, 由界面上的
// 对话框读出来并调 `resolveConfirm` 执行。**不返回 Promise**: 调用点往往是同步的 (菜单点击、
// 开关切换), 让它们 await 会把整条链路染成异步。
//
// 不用 `window.confirm`: 它在 WebView 里不一定真的弹出来, "询问"会静默变成"直接放行"。

import { useAppStore } from './state/store.svelte';

export interface PendingConfirm {
  title: string;
  /** 补充说明 (可以是多段文字) */
  description?: string;
  /** 确认按钮的文案 */
  confirmLabel?: string;
  /** 取消按钮的文案 */
  cancelLabel?: string;
  /** 危险操作 (确认按钮变成红色实心) */
  danger?: boolean;
  /** 提示性操作 (蓝色实心, 用于"知道了"这类) */
  info?: boolean;
  /** 用户确认后执行 */
  action: () => void;
}

/** 当前待处理的请求; `null` 表示没有。 */
let pending: PendingConfirm | null = null;

/** 请求一次确认。 */
export function requestConfirm(options: PendingConfirm): void {
  pending = options;
  useAppStore.getState().setConfirmDialog(true);
}

/** 请求一次纯提示 (只有一个"知道了"按钮)。 */
export function requestAlert(title: string, description?: string): void {
  requestConfirm({ title, description, confirmLabel: '知道了', info: true, action: () => {} });
}

/** 界面读取当前请求。 */
export function pendingConfirm(): PendingConfirm | null {
  return pending;
}

/** 界面回执: 用户选了确认或取消。 */
export function resolveConfirm(accepted: boolean): void {
  const current = pending;
  pending = null;
  useAppStore.getState().setConfirmDialog(false);
  if (accepted && current) current.action();
}
